mapper.select:
SELECT id, order_no, title, content, event_type
FROM admin_work_order
WHERE is_deleted = 0 AND is_archived = 0
  AND category = #{category}

  AND sub_category = #{subCategory}
  AND (
      region = #{region}
      OR region IS NULL OR region = ''
      OR region LIKE CONCAT(#{region}, '%')
      OR #{region} LIKE CONCAT(region, '%')
  )
  AND create_time >= #{start}
ORDER BY id ASC
LIMIT #{limit}

SELECT id, order_no, title, content, category, sub_category, level, attention_count, event_type, confidence,
       hit_keywords, need_review, region, department, street_office, status, is_overdue,
       dispose_tag, create_time, close_time
FROM admin_work_order
WHERE is_deleted = 0
AND is_archived = #{archived}
AND order_no LIKE CONCAT('%', #{orderNo}, '%')
AND category = #{category}
AND level = #{level}
AND region LIKE CONCAT(#{region}, '%')
AND status = #{status}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
AND create_time >= #{startDate}
ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM admin_work_order
WHERE is_deleted = 0
AND is_archived = #{archived}
AND order_no LIKE CONCAT('%', #{orderNo}, '%')
AND category = #{category}
AND level = #{level}
AND region LIKE CONCAT(#{region}, '%')
AND status = #{status}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
AND create_time >= #{startDate}

SELECT COUNT(1)
FROM admin_work_order
WHERE is_deleted = 0 AND status = 'PENDING_DISPATCH'
AND is_archived = #{archived}
AND order_no LIKE CONCAT('%', #{orderNo}, '%')
AND category = #{category}
AND level = #{level}
AND region LIKE CONCAT(#{region}, '%')
AND status = #{status}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
AND create_time >= #{startDate}

SELECT id, order_no, title AS summary, department, street_office, dispose_tag,
       dept_audit_user_name, dept_audit_time, is_overdue, level, category,
       sub_category, region, create_time, close_time, archive_time
FROM admin_work_order
WHERE is_deleted = 0 AND is_archived = 1
AND category = #{department}
AND street_office = #{streetOffice}
AND dispose_tag = #{disposeTag}
AND is_overdue = #{isOverdue}
ORDER BY archive_time DESC, id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM admin_work_order
WHERE is_deleted = 0 AND is_archived = 1
AND category = #{department}
AND street_office = #{streetOffice}
AND dispose_tag = #{disposeTag}
AND is_overdue = #{isOverdue}

SELECT id, order_no, title AS summary, department, street_office, category, level,
       archive_time, archive_type, close_time
FROM admin_work_order
WHERE is_deleted = 0 AND is_archived = 1
AND YEAR(archive_time) = #{year}
AND category = #{department}
AND category = #{category}
ORDER BY archive_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM admin_work_order
WHERE is_deleted = 0 AND is_archived = 1
AND YEAR(archive_time) = #{year}
AND category = #{department}
AND category = #{category}

SELECT id, order_no, title, content, category, sub_category, level, region, department,
       street_office, status, is_overdue, deadline, create_time, update_time,
       dispose_tag, dept_audit_status, final_audit_status, hit_keywords, confidence,
       dept_receive_time, street_receive_time
FROM admin_work_order
WHERE is_deleted = 0

    AND category = #{department}
    AND status NOT IN ('PENDING_DISPATCH', 'PENDING_REASSIGN')


    AND street_office LIKE CONCAT(#{streetOffice}, '%')
    AND status NOT IN ('PENDING_DISPATCH', 'PENDING_REASSIGN', 'PENDING_DEPT_PROCESS', 'PENDING_DEPT_ASSIGN')

AND order_no = #{orderNo}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM admin_work_order
WHERE is_deleted = 0

    AND category = #{department}
    AND status NOT IN ('PENDING_DISPATCH', 'PENDING_REASSIGN')


    AND street_office LIKE CONCAT(#{streetOffice}, '%')
    AND status NOT IN ('PENDING_DISPATCH', 'PENDING_REASSIGN', 'PENDING_DEPT_PROCESS', 'PENDING_DEPT_ASSIGN')

AND order_no = #{orderNo}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
AND create_time >= #{startTime}
AND create_time <= #{endTime}

SELECT id, order_no, title AS summary, street_office, dispose_tag, dispose_time,
       is_overdue, level, category, dept_return_count
FROM admin_work_order
WHERE is_deleted = 0 AND status IN ('PENDING_EVALUATE', 'EVALUATED', 'STREET_DONE')
AND category = #{department}
AND street_office = #{streetOffice}
AND dispose_tag = #{disposeTag}
AND is_overdue = #{isOverdue}
AND dispose_time >= #{startTime}
AND dispose_time <= #{endTime}
ORDER BY dispose_time ASC, id ASC
LIMIT #{offset}, #{size}

SELECT COUNT(*) AS order_total, SUM(CASE WHEN status = 'PENDING_STREET_PROCESS'
OR status IN ('PENDING_DEPT_ASSIGN', 'STREET_REJECTED')
THEN 1 ELSE 0 END) AS pending_handle, SUM(CASE WHEN status = 'PENDING_DEPT_PROCESS' THEN 1 ELSE 0 END) AS pending_verify, SUM(CASE WHEN status = 'PENDING_DEPT_ASSIGN' THEN 1 ELSE 0 END) AS pending_assign, SUM(CASE WHEN status IN ('PENDING_EVALUATE', 'EVALUATED', 'STREET_DONE') THEN 1 ELSE 0 END) AS pending_audit, SUM(CASE WHEN year(dispose_time) = #{year} AND month(dispose_time) = #{month} THEN 1 ELSE 0 END) AS month_done, COALESCE(AVG(CASE WHEN dept_score IS NOT NULL THEN dept_score END), 0) AS avg_score FROM admin_work_order WHERE is_deleted = 0 AND category = #{category} AND street_office = #{region}

SELECT COUNT(1)
FROM admin_work_order
WHERE is_deleted = 0 AND status IN ('PENDING_EVALUATE', 'EVALUATED', 'STREET_DONE')
AND category = #{department}
AND street_office = #{streetOffice}
AND dispose_tag = #{disposeTag}
AND is_overdue = #{isOverdue}
AND dispose_time >= #{startTime}
AND dispose_time <= #{endTime}

