SELECT COALESCE(SUM(wo.attention_count), 0)
FROM admin_work_order wo
WHERE wo.is_deleted = 0
  AND wo.create_time >= #{start}
AND wo.category = #{category}
AND wo.sub_category = #{subCategory}
AND wo.region LIKE CONCAT(#{region}, '%')

SELECT wo.title, wo.content
FROM admin_work_order wo
WHERE wo.is_deleted = 0
  AND wo.create_time >= #{start}
AND wo.category = #{category}
AND wo.sub_category = #{subCategory}
AND wo.region LIKE CONCAT(#{region}, '%')
ORDER BY wo.create_time DESC
LIMIT 50

SELECT wo.order_no, wo.title, wo.content, wo.category, wo.sub_category,
       wo.region, wo.attention_count, wo.status
FROM admin_work_order wo
WHERE wo.is_deleted = 0
  AND wo.create_time >= #{start}
AND wo.category = #{category}
AND wo.sub_category = #{subCategory}
AND wo.region LIKE CONCAT(#{region}, '%')
ORDER BY wo.attention_count DESC, wo.create_time DESC
LIMIT 20
